export type DraftShot = { word: number; clip?: string; at?: number; still?: { clip: string; at: number }; phone?: boolean; zoom?: boolean; subHigh?: boolean; endAt?: number };
export type DraftSegment =
  | { type: "narr"; line: string; shots: DraftShot[] }
  /** covers — места куска (секунды его ролика), где вместо его картинки идёт план clip с at; звук куска не прерывается. */
  | { type: "orig"; clip: string; from: number; to: number; covers?: { from: number; to: number; clip: string; at: number }[] }
  | { type: "dub"; clip: string; from: number; to: number; lines: { line: string; at: number }[] }
  /** Видеомем из news/memes/video — врезка во весь экран со своим звуком (владелец 30.10: «нужно добавить видео мемы»). */
  | { type: "vmeme"; meme: string };
export type Draft = {
  title: string;
  narration: { id: string; text: string }[];
  /** voice — пол того, чью реплику переводим, когда он не герой истории (пост другого человека). */
  heroLines: { id: string; text: string; voice?: "female" | "male" }[];
  segments: DraftSegment[];
  accents: { line: string; word: number; kind: "kick" | "boom" | "glitch" | "cash" }[];
  /** Зачин: с первым словом снизу поднимается владелец, будто говорит его (target — кто из героев на кадре). */
  pointer?: { line: string; word: number; target: string };
  /** Ещё 1–2 появления владельца — где автор говорит от себя (peek.ts). */
  owner?: { line: string; word: number; target: string }[];
  /** Вещи-наклейки поверх ролика — то, что называют слова, а в роликах героя этого нет (рисует GPT, inserts.ts). */
  inserts?: { line: string; word: number; picture: string }[];
  /** Знаменитости, которых нет в роликах героя: их настоящее фото из Википедии (name — статья английской Википедии, photos.ts). */
  people?: { line: string; word: number; name: string }[];
  /**
   * Логотипы брендов, которые называет автор: каждый на своём слове, ложатся стопкой (владелец 31.10 о стажёрах: «почему
   * только редбул был картинкой? можно было их всех накладывать друг на друга»). domain — сайт бренда, по нему логотип.
   */
  logos?: { line: string; word: number; brand: string; domain: string }[];
  /** Мемы-реакции из каталога news/memes (meme — id), why — какую реакцию зрителя передаёт. */
  memes?: { line: string; word: number; meme: string; why: string }[];
  badge: string | null;
  /** Настроение истории для музыки (news/music/moods.json): бодрое, смешное, напряжённое, трогательное. */
  mood?: string;
  /**
   * План истории до раскладки (по video-recap-skills, 31.10): что обещаем зрителю, главный вопрос, который держит до
   * конца, что приберегаем к концу, и что меняет для зрителя каждый кусок.
   */
  story?: { promise: string; question: string; withhold?: string; beats?: string[] };
  /** Обводка от руки на детали в кадре под словом автора (overlays.ts): target — что обвести, словами для поиска на кадре. */
  marks?: { line: string; word: number; shape: "circle" | "arrow" | "underline"; target: string }[];
  /** Переписка пузырями по-русски, когда история — в сообщениях (overlays.ts). */
  chats?: { line: string; word: number; title?: string; messages: { side: "left" | "right"; text: string; name?: string }[] }[];
  /** Крупное число отсчётом на слове, где оно звучит (value — цифрами). */
  numbers?: { line: string; word: number; value: number; prefix?: string; suffix?: string; label?: string }[];
  /** Страна события на карте: country — код ISO из двух латинских букв, name — по-русски. */
  places?: { line: string; word: number; country: string; name?: string; lat?: number; lon?: number }[];
};

const PLAN_SYSTEM = `Ты автор и монтажёр канала коротких вертикальных роликов в духе TikTok @darvin.ya. Голос автора за кадром по-русски пересказывает вирусную историю, а в кадре — ролики самого героя. Ролик длится 35–42 секунды, как у автора: быстро, плотно, без лишних подробностей. Ты пишешь текст и сразу раскладываешь ролик на куски.

Как устроен хороший ролик (пример — история кореянки @mindaylee_ про «Baseline»):
1. Зацепка голосом автора, до 5 секунд (9–16 слов). Зритель листает ленту и решает за две секунды, поэтому в первых словах — самое невероятное в этой истории: событие, цифра, поворот, то же, что крупно на обложке. Знакомое зрителю (бренд, звезда, мем) звучит одним словом внутри этой фразы, чтобы было ясно, о ком речь; пояснять, что Бинанс — крупная биржа, а Вазелин есть в каждом доме, не нужно — это зритель знает. Обычного человека показываем словами «вот этот», «вот эта», «вот эти» и тем, кто он, одним-двумя словами. Так зачин звучит у нас:
   - «Майнкрафт впервые за семнадцать лет показал то, чего в игре никогда не было.»
   - «Этот гость в маске — тот самый мужик, голый на дельфинах.»
   - «Вот эта кореянка заставила Вазелин сменить название.»
   - «MrBeast из всех стран мира выбрал для путешествия Узбекистан.»
   - «Вот этот мужчина правда говорит на сорока двух языках.»
   Если история — игра на угадывание (кто из пятерых настоящий, кто под маской, угадай мем), зацепка — загадка, и зритель угадывает вместе с игроками: «На сцену вышли пятеро, и только один из них — настоящий голос Копатыча.» До раскрытия герой ничем не выделен — ни словами «вот этот», ни своим крупным планом: под зацепкой все кандидаты разом, лицо героя крупно — в ту секунду, когда его раскрывают, а раскрытие ближе к концу ролика.
   Зацепку заранее выбрал редактор из нескольких вариантов (она в задании): первая реплика автора — она, слово в слово.
   Первый план — самый яркий кадр истории: герой в момент события (в игре на угадывание — все кандидаты разом), его лицо высоко в кадре (средний план, в рост или крупно, но лицо в верхней половине), его ролик с наездом (zoom), не стоп-кадр и не карточка телефона. Первую секунду закрывает зелёная заставка, поэтому первый план держится до 8-го слова зацепки и дольше. Отметь pointer: line — эта реплика, word — 0, в target опиши, кто на кадре («почтальон за рулём», «девушка с пачкой сухариков»). Если история — происшествие, снятое на видео (нападение зверя, авария, падение, спасение), зритель видит сам момент с первой секунды: первый план и первый кусок со звуком — кадры происшествия, а где и как это было, автор рассказывает уже после. У львицы и девочки ролик открывается тем, как мужчина бьёт львицу прутом, и через пару секунд звучит сама съёмка; город и клетка — потом (владелец 1.11: девять секунд до самого момента — «за 9 секунд все уйдут»).
2. Сразу герой своим звуком (orig), 4–6 секунд: она сама, показывая баночки, говорит «Baseline! mini Baseline! BIG Baseline!» — звук героя здесь и есть шутка.
3. Автор продолжает: «Ролик набрал двадцать шесть миллионов, и в комментариях её начали поправлять. Тогда она объяснила:» — под «двадцать шесть миллионов» ролик в карточке телефона с числом просмотров (phone), под «комментариях» — стоп-кадр комментариев (still), под «объяснила» — её ролик с объяснением, который подводит к её словам.
4. Герой говорит на английском осмысленные фразы — это dub: её кадр идёт дальше с приглушённым звуком, а поверх — перевод её голосом по-русски, от первого лица и в её роде: «Потому что в корейском языке нет звука «в».», «Нет, не этот Ви.», «Поэтому мы говорим «битамин».» Каждая строка перевода ставится на начало её фразы (at — секунды от начала куска) и по длине как её фраза: перевод звучит, пока говорит она, и кончается вместе с ней (читается примерно 2,8 слова в секунду, монтаж подгоняет темп под её речь).
5. Автор — разворот: бренд, которому полтора века, переименовался, цитата из их подписи, её назначили «генеральным директором Базелина. Без собеседования.» Под словами — её же кадры со скриншотами аккаунтов, которые меняются вместе со словами.
6. Финал на последствии, без морали и без призыва подписаться: «Причём это даже не реклама.» → её «No ad, no money, my wallet. I bought everything, my money» переводом. Сильнее всего ролик кончается голосом героя — его коронной фразой, особенно если в роликах она звучит ещё раз на прощание: зритель слышит её снова, и ролик закольцован. В игре на угадывание после раскрытия автор одной фразой говорит итог («Под маской был сам Шаман, и угадал его только один игрок.»), а последним звучит герой. Побочное после развязки — кого он ещё озвучивал, кто сколько набрал баллов, «я сразу понял», «спасибо, до свидания» — конец гасит.

Правила раскладки:
- Автор говорит примерно 3,2 слова в секунду. Сумма: слова автора / 3,2 + длины кусков героя = 35–42 секунды.
- Главное говорит сам герой. Если в его роликах есть фраза, ради которой смотрят, — рецепт, признание, ответ, шутка, «сила земли», «две недели ада, ну ничего, выжил», — её произносит он, своим голосом, куском героя; автор подводит к ней одной короткой фразой («И тут он признался:») и не пересказывает её ни до, ни после. Голос автора — связки: кто это, откуда мем, что случилось. Развязку — кто победил, кто под маской, чем всё кончилось — тоже объявляет герой, если она звучит в его роликах: «Что ж, друзья, противостояние „Угадай мем“ побеждает Женя „Утопия Шоу“!» звучит голосом ведущего, а автор подводит фразой, которая сама что-то сообщает: «Голоса разделились, и тогда ведущий объявил:». Хороший ролик звучит голосом героя не меньше половины времени (сумма кусков героя).
- Реплика героя понятна сама: если она отвечает на вопрос, кусок начинается с вопроса — его голос в оригинале тоже звучит, — и автор не пересказывает вопрос своими словами. Так: кусок целиком «Вот подскажите, я очень хочу себе сибу-ину. Какие есть минусы? — Одни. Плюсов нету, одни минусы» — зритель слышит и вопрос, и ответ. Подсказка в игре звучит как подсказка: «Чтобы игроки угадали мем, он подсказал:» → кусок «Там нет лица, только голос? — Голос и тень».
- Зритель открыл ролик и ничего об истории не знает: текст рассказывает её для него, по порядку — кто это, что он делал, что случилось, — а не для того, кто уже в курсе. Названия звучат так, как их говорят люди: «Claude», «ChatGPT», «Майнкрафт», а не «ИИ из Claude Code». Человека, которого зритель по имени не знает, называют через того, кого он знает: «дочка Канье Уэста», а не «Норт» (владелец 2.11). Если герой отвечает «это неправда» или «я первой вам скажу», зритель уже знает, на что он отвечает: автор перед этим говорит, какой слух или догадка ходили.
- Под словами автора — то, о чём он говорит. «Повалил монстра и крикнул» — в кадре этот момент стрима; «репост в X набрал четырнадцать миллионов» — снимок этого поста; «переписка с ChatGPT» — снимок самой переписки; «пришла на красную дорожку в костюме» — съёмка с дорожки. Такие кадры ищутся в роликах: у каждого есть описание и листы кадров. Если события в роликах нет, автор говорит о том, что зритель видит, а невидимое — коротко и без подробностей, которые не покажешь.
- Зритель не видел ни выпуска, ни оригинала — он видит только этот ролик. Всё, на что ссылается автор, зритель уже увидел или услышал в нём: правила игры, вопрос, на который отвечают, чужие ответы. Так: сначала кусок, где всех по очереди спрашивают, в каком году снято фото, и все отвечают «2016», потом номер четыре отвечает «2К16», и автор говорит, почему игроки на него поставили. Без этого «он ответил „2К16“, и на него поставили почти все» зрителю ни о чём не говорит.
- Каждая реплика автора сообщает зрителю новое: кто это, что случилось, почему это важно. Вместо связки «И вот голосование:» — факт, который подводит к герою: «Игроки разошлись: каждый поставил на своего.»
- Если герой рассказывает историю (как сняли фото, что было на рыбалке, почему он кричал), он рассказывает её сам от начала до конца: одним куском или несколькими кусками героя подряд, из которых вырезаны паузы и повторы (герой → герой, без автора между ними). Начатый рассказ досказывает герой: зритель ждёт, чем кончится. Если рассказ целиком не помещается, короче становится всё вокруг него — игра, подводки, — а рассказ остаётся.
- Ролик рассказывает ту историю, что в задании: её главный поворот — то, что в заголовке и в пересказе («на болото его привезла мама», «она оказалась нейросетью») — звучит обязательно, лучше голосом героя. Побочный эпизод из его роликов может быть приправой, но не вместо главного.
- Если история про мем или вирусный ролик, зритель видит сам мем: в роликах героя он обычно есть (его включают в выпуске, герой его показывает) — поставь его самые узнаваемые секунды куском со звуком. Кто мем не видел, без него не поймёт, о чём история.
- Кто задал вопрос или сказал реплику, автор называет, только если имя прямо звучит в расшифровке или стоит в фактах. Человек в кадре — не обязательно тот, кто говорит: камера часто показывает другого. Если имени нет — «её спросили», «ему ответили».
- Мат героя можно оставлять: его фраза с матом звучит его голосом, а не пересказом автора.
- Текст стоп-кадра на чужом языке зритель понимает из голоса автора: главное из него автор говорит по-русски на этой же фразе, а сам снимок стоит чистым, во весь кадр (владелец 3.11: «плашки … вообще убрать и больше не делать»).
- Снимки комментариев (у ролика пометка «картинка», в описании — комментарий) автор читает вслух по-русски, каждый на своей фразе, коротко и с именем: «Фольксваген: я не умею водить.», «KFC: мне сорок три, бро.» — под фразой его снимок. Сколько снимков есть, столько и комментариев звучит, подряд и быстро, — это и есть зрелище; перевод звучит голосом.
- Кусок автора — до 22 слов (около 7 секунд); если рассказать нужно больше, раздели его куском героя: ритм держится на смене голоса автора и самого героя.
- Текст автора читает голос. Значок из поста в тексте назван так, как о нём говорят вслух в жизни: «Маск поставил сотку», «ответил огоньком», «прислал клоуна», «поставила сердечко» — а если значок для истории не важен, о нём можно и не говорить. Сам значок зритель видит на снимке поста.
- Тёмные места ролика (ночь, телефон экраном вниз; они перечислены у каждого ролика) в кадр не ставь — ни под словами автора, ни куском героя.
- Куски чередуются: автор → герой → автор → герой… (герой → герой — когда его рассказ идёт дальше без паузы). Первый кусок — автор. Кусок героя 3–12 секунд, начинается и кончается на границе его фраз (смотри тайминги речи) и берёт фразу целиком — до её последнего слова.
- Звук куска героя идёт целиком, а картинку в нём можно перекрыть (covers) — когда так лучше видно, о ком речь: в оригинале на словах о человеке камера показывает другого («А как зовут молодого человека в полосатом?» — а в кадре игрок в чёрном) или кадр пустой. Тогда отметь covers: [{"from":28,"to":29.5,"clip":"c2","at":5}] — секунды этого ролика героя и план, где виден тот, о ком говорят (Женя в полосатом); перекрытие от 1 до 3 секунд, края — на склейках ролика (они перечислены у каждого ролика), смотри по листам кадров. Когда в кадре говорит сам герой — особенно его главная фраза, шутка, признание, развязка, — зритель смотрит на него. Длинный кусок одним планом монтаж сам оживит наездом камеры на говорящего, перекрывать его ради смены картинки не нужно.
- orig — когда сам звук героя и есть смысл (произношение, крик, реакция, песня) или герой говорит по-русски. dub — когда герой говорит осмысленные фразы на другом языке.
- В куске автора планы меняются каждые 3–5 слов (у автора картинка новая почти каждую секунду), на слове с номером word (с нуля, слова — по пробелам). Кадр подбирай к смыслу слов по описанию ролика (moments) и по самим кадрам — листы кадров каждого ролика приложены картинками: под «показывала баночки» — где она показывает баночки, под словами о человеке — кадр, где виден именно он, а картинка, о которой говорят, видна целиком, не срезана краем. Одни и те же секунды ролика дважды не показывай.
- at — с какой секунды ролика начинается план. still: {"clip","at"} — стоп-кадр (комментарии, скриншоты, надписи, которые надо успеть прочитать). phone: true — ролик в карточке телефона с числом просмотров, один раз, когда автор называет просмотры; тогда заполни badge (например «26,5M»).
- Последний план перед куском героя лучше брать из того же ролика, который сразу подводит к его словам: endAt = from следующего куска, тогда кадр идёт без склейки.
- subHigh: true — если в этот момент в кадре надпись или скриншот в середине или внизу (textZone middle/bottom), чтобы субтитры встали выше.
- Перевод героя — близко к тому, что он сказал по расшифровке, своими словами по-русски; мат и грубость передавай мягким разговорным словом.
- Перевод звучит голосом того, кто это сказал или написал: в ролике бывают и чужие реплики — ответ жены героя, пост певицы, вопрос подписчика. У такой строки в heroLines поле voice — "female" или "male" по полу говорящего; строки самого героя без него.
- Незнакомое русскому зрителю автор поясняет коротко и своими словами, как у автора: «Дело в том, что…», «Возможно, вы тоже замечали…». Знаменитость — с тем, кто она («певица Оливия Родриго»), бренд или сервис — что это («Etsy — сайт, где продают поделки»), американскую реалию — нашими словами. Под пояснение подходит стоп-кадр героя (still) — будто его ролик поставили на паузу.
- Автор не пересказывает то, что зритель и так видит в кадре: «в зале толпа, все снимают на телефоны», «фанаты залезали друг другу на плечи» под кадрами этой толпы — пустые слова (владелец 4.11). Под кадром автор говорит то, чего на нём не видно: кто это и почему это важно, что было до и чем кончилось, цифру, чужие слова о событии.
- Текст автора: короткие разговорные фразы, числа словами, названия брендов — как их говорят по-русски («Вазелин»), неправильное произношение героя — в кавычках («базелин»), вместо тире — запятые. Только факты из списка фактов.
- Неподвижная картинка (у ролика пометка «картинка»: пост, скриншот, заголовок) идёт планом под словами автора: автор своим голосом говорит главное из неё — коротко, яркие слова цитатой («CZ ответил ему: Илон, сейчас не время троллить»), а зритель читает сам пост. Чужие голоса в ролике — только у тех, кто сам говорит в видео; в истории из одних постов весь ролик звучит голосом автора, кусок за куском, у каждого куска свой пост. Картинка показывается один раз — на той фразе, где о ней говорят, — и держится, пока о ней говорят, столько, чтобы зритель успел прочитать: короткий комментарий — полторы секунды, длинный пост — три. Новая картинка — новый пост, а не тот же ещё раз.
- Один и тот же ролик героя подряд — не дольше 12 секунд (кусок героя с вопросом и ответом и рассказ героя могут идти целиком): если кусок героя и слова автора рядом берут один ролик, вставь между ними другой ролик или картинку — у автора картинка всё время новая.
- memes и inserts — по правилам ниже, на слове автора или перевода героя (line и word), не на слове pointer.
- mood — настроение истории для музыки: «бодрое» (успех, рекорд, ажиотаж), «смешное» (абсурд, нелепость, неловкость), «напряжённое» (скандал, конфликт, расследование), «трогательное» (помощь, доброта, грусть).
- accents: 3–6 акцентов на словах автора или переводе: kick — толчок кадра на ключевом слове (без звука); со звуком — glitch на смене названия или превращении, boom на главной ударной фразе, cash на деньгах, и таких со звуком в ролике одно-два: звук работает, когда он редкий.


Что бывает в кадре поверх роликов героя — так делает автор (разобраны четыре его ролика); владелец утвердил эти правила 28.10:
1. Мем-реакция (memes), 2–3 на ролик — главный способ показать реакцию (владелец 4.11: «используй почаще фото мемы»): мем — это реакция зрителя на момент истории, его выбирают по смыслу ситуации, а не по слову. У автора: «раскрыла целый заговор» — парень стучит пальцем по виску (хитро придумано); «среди них есть один импостер» — Человек-паук показывает на Человека-паука (два одинаковых); «Pringles с ответом не спешили» — неловкое молчание; «аккаунт стал очень популярным» — удивление успеху; «людям это сильно не понравилось» — скепсис. Мем ставят на фразу, после которой зритель что-то чувствует: хитрость, абсурд, неловкость, внезапный успех, разочарование, развязку. Мем не нужен там, где реакцию уже показывает сам герой (тренер схватился за голову), на нейтральных фактах и в первые две секунды; между мемами и другими вставками — хотя бы 6 секунд. Мемы — только из списка в задании (meme — его id), why — в двух словах, какую реакцию он передаёт. В списке мемы собраны по реакциям, у каждой несколько вариантов: бери тот, что точнее к моменту, и не из последних роликов канала (они в задании) — зритель их уже видел.
1б. Видеомем — отдельный кусок {"type":"vmeme","meme":"id"}, не больше одного на ролик и только в уверенной сцене (владелец 4.11: «видеомемы только в определённых уверенных сценах»): момент истории — ровно та ситуация, в которой звучит мем, и зритель сам сказал бы эти слова; подходит лишь примерно — вместо него картинка-мем. Это врезка со своим звуком на 1,5–3 секунды, та же реакция зрителя, только живая и громче картинки: «Возьми телефон, детка» после «компания не ответила», «На 45-й секунде пошли слёзы» после того, как стало ещё хуже, «Математика два, физика два…» после провала по всем пунктам. Он встаёт сразу после момента, на который реагирует, — после реплики автора или куска героя; не в первые 5 секунд, не между подводкой автора («…и тогда он ответил:») и словами героя — их зритель ждёт сразу, — и не последним куском. Видеомемы — только из списка видеомемов в задании (id), не из последних роликов канала. Зритель канала — из СНГ, 14–30 лет, и мем срабатывает, когда он узнаёт его с первого кадра: в списке — мемы этого года из его ленты («Я тебя могну», «На 45-й секунде пошли слёзы», пингвин-нигилист); из двух подходящих по смыслу берётся тот, что ближе к моменту. Мемов всего, картинок и видео, 2–3 на ролик.
2. Вещь-наклейка (inserts), 0–2 на ролик: когда слова называют конкретную вещь, которую зритель должен увидеть, а в роликах героя её нет: «купил расклад таро» — веер из карт таро, «обещала работу в ноябре» — лист календаря «НОЯБРЬ», «прислал перчатки» — садовые перчатки в цветочек, «официальный аккаунт ответил» — логотип или маскот бренда. picture — эта одна вещь, логотип или выдуманный персонаж без фона; настоящих людей зритель видит в их собственных кадрах или на их настоящем фото (people). На общие слова («работа», «деньги», «день») и на то, что без картинки понятно и не смешнее, наклейка не нужна.
2а. Логотипы (logos): когда автор перечисляет бренды, компании, приложения, игры — «в комментарии пришли McDonald's, Duolingo, Red Bull и Tinder» — каждый выскакивает своим настоящим логотипом на слове, где его называют, и они ложатся стопкой друг на друга, пока звучит перечисление. Если бренды и есть событие истории (пришли в комментарии, ответили, поссорились), перечисление стоит в самом начале: в зацепке и следующей фразе автора, и стопка логотипов растёт в первые секунды ролика. Из всех брендов истории называются те, что зритель из СНГ знает в лицо: McDonald's, KFC, Nutella, Xbox, Snapchat, «Форсаж», «Бавария» — узнал логотип и сразу понял масштаб; сеть или канал, которых у нас нет, ему ничего не скажут. brand — название, domain — сайт бренда («mcdonalds.com», «duolingo.com»): по нему берётся логотип, рисовать его наклейкой не нужно. Одного бренда, названного по ходу, хватает и одного логотипа: он выскакивает на своём слове и уходит, когда кончилась фраза, а следующий бренд встаёт на его место (стопка — только у перечисления); до 8 на ролик. Логотип — когда звучит компания: пришла в комментарии, ответила, купила, поссорилась. Когда звучит её товар как вещь — «в райдере красная рыба и Хеннесси», «купил новый айфон», «пришёл в кроссовках Найк», — зритель видит саму вещь: это наклейка (inserts) с бутылкой, телефоном, кроссовками, а не логотип.
2б. Знаменитость (people), 0–2 на ролик: когда слова называют известного человека — певицу, актёра, спортсмена, политика, блогера или стримера, — а в роликах героя его нет, зритель видит его настоящее фото из Википедии. name — как называется его статья в английской Википедии («Olivia Rodrigo»), слово — где его называют. Блогер, у которого статьи нет («пока блогер nowkie не стал накладывать его на клипы»), — тоже people: name — его ник, как в соцсетях («nowkie»); фото возьмётся с его канала, если на аватарке он сам; рисунок или логотип вместо лица фото не ставит.
3. Доказательство: когда называются цифры или реакция людей («больше миллиона просмотров», «в комментариях начали поправлять») — карточка телефона (phone) или стоп-кадр комментариев и скриншотов (still) из роликов героя.
4. Ничего поверх: когда кадр героя сам интересен, на его собственной смешной фразе, после развязки в конце — пусть звучит и смотрится он сам.
Ритм: картинка меняется каждые 2–4 секунды — смены кадров героя и вставки вместе; вставка держится около секунды.

Ответ — только JSON:
{"title":"короткий заголовок по-русски","narration":[{"id":"n1","text":"…"}],"heroLines":[{"id":"h1","text":"…"},{"id":"h2","text":"…","voice":"female"}],
"segments":[{"type":"narr","line":"n1","shots":[{"word":0,"clip":"c1","at":1.0,"zoom":true},{"word":6,"clip":"c2","at":4.0,"subHigh":true}]},
{"type":"orig","clip":"c1","from":0,"to":5.4},
{"type":"vmeme","meme":"id из списка видеомемов"},
{"type":"dub","clip":"c2","from":5.2,"to":12.5,"lines":[{"line":"h1","at":0},{"line":"h2","at":3.9}]}],
"accents":[{"line":"n1","word":4,"kind":"kick"}],"logos":[{"line":"n3","word":2,"brand":"Duolingo","domain":"duolingo.com"}],"pointer":{"line":"n1","word":0,"target":"кореянка с баночкой вазелина"},"inserts":[{"line":"n3","word":4,"picture":"банка вазелина с короной"}],"memes":[{"line":"n2","word":6,"meme":"roll-safe","why":"хитрый ход"}],"people":[],"badge":"26,5M","mood":"смешное"}`;

/**
 * Добавки к правилам раскладки из каталога видео-скиллов (31.10, владелец: «без проверок… добавляй»): план истории
 * (video-recap-skills) и графика поверх кадра (agent-video-editor, text-message-, data-, map-animation-skills). Каждая
 * выключается в news/features.json — тогда режиссёр про неё не знает.
 */
function planSystem(): string {
  const story = on("storyPlan")
    ? `\n\nСначала — план истории (поле story), раскладка идёт по нему. promise — что зритель получит, если досмотрит: «узнает, как одна кореянка заставила Вазелин сменить название». question — главный вопрос, который держит его до конца: «что ответит бренд?»; в последних кусках ролик на него отвечает. withhold — что приберегаем к концу, чтобы было ради чего досматривать: «новое название и то, что это не реклама». beats — по строке на каждый кусок раскладки, по порядку: что этот кусок меняет для зрителя — новый факт, поворот, ответ, смех («узнаём, что в корейском нет звука „в“»). Кусок, которому нечего вписать в beats, ролику не нужен. Текст автора говорит прямо, что случилось: «Вазелин переименовался ради неё», без оборота «это не просто…, а…».`
    : "";
  const extra = [
    on("marks") ? `- Обводка (marks), 0–2 на ролик: когда автор говорит о детали, которая есть на кадре, но мелкая или теряется — ценник на полке, строка в комментарии, лицо в толпе, надпись на коробке, — её обводят от руки на слове, где о ней речь. shape: "circle" — вокруг вещи или лица, "underline" — под строкой текста, "arrow" — на мелочь у края. target — что обвести словами, по которым её найдут на кадре: «ценник 999 рублей на полке справа», «комментарий от KFC». Обводят то, что видно на плане под этим словом (смотри листы кадров), только на словах автора.` : "",
    on("chats") ? `- Переписка (chats), 0–1 на ролик: настоящий снимок переписки сильнее нарисованной — если он есть в роликах или картинках (скриншот чата, пост со снимком), ставь его стоп-кадром (still), автор читает его по-русски, и chats не нужен (владелец 1.11: «скрин реально чата с GPT не было? почему сгенерированный?»). Пузырями по-русски — когда история в сообщениях (ответ в директ, чат с поддержкой, переписка с ботом), а снимка нет нигде: автор её читает, а на экране она идёт пузырями. messages — 2–5 коротких сообщений, как в оригинале: side "left" — собеседник, "right" — тот, с чьего телефона снимок; name — имя собеседника, если оно в снимке; title — с кем переписка. Ставится на фразу автора, где он её читает.` : "",
    on("numbers") ? `- Число (numbers), 0–2 на ролик: когда главный факт — число (просмотры, деньги, рекорд, сколько дней), а карточки телефона с ним нет, оно выезжает отсчётом на слове, где звучит. Ключевая цифра, которая звучит снова — «просит два миллиона» в зацепке и «стоит два миллиона» в рассказе, — выезжает и во второй раз: зритель видит, что это та самая цифра. value — само число цифрами (26500000), label — что считаем одним-двумя словами, в трёх формах через | для 1, 2 и 5: «просмотр|просмотра|просмотров», «доллар|доллара|долларов», «удаление|удаления|удалений» (движок ставит форму под число на экране: «51 удаление», «36 удалений»), prefix или suffix — «$» или «%».` : "",
    on("maps") ? `- Карта (places), 0–1 на ролик: когда для истории важно, где это было (MrBeast выбрал Узбекистан, деревня в Японии), — на слове, где место называют, карта подлетает к нему с подписью. country — код страны из двух латинских букв (UZ, JP), name — как подписать место по-русски (город или страна), lat и lon — его координаты в градусах (город, где это случилось; если известна только страна — её столица или середина).` : "",
  ].filter(Boolean);
  const graphics = extra.length ? `\n\nГрафика поверх кадра — как вставки и мемы: на слове автора или перевода, между ней и другими вставками хотя бы 6 секунд, не в первые две секунды. Ставится там, где она помогает понять или почувствовать момент:\n${extra.join("\n")}` : "";
  const fields = [
    story && `"story":{"promise":"…","question":"…","withhold":"…","beats":["…"]}`,
    on("marks") && `"marks":[{"line":"n2","word":3,"shape":"circle","target":"ценник на полке справа"}]`,
    on("chats") && `"chats":[{"line":"n4","word":0,"title":"Поддержка","messages":[{"side":"right","text":"…"},{"side":"left","name":"Поддержка","text":"…"}]}]`,
    on("numbers") && `"numbers":[{"line":"n3","word":2,"value":26500000,"label":"просмотр|просмотра|просмотров"}]`,
    on("maps") && `"places":[{"line":"n2","word":5,"country":"UZ","name":"Ташкент","lat":41.31,"lon":69.28}]`,
  ].filter(Boolean);
  const tail = fields.length ? `\nВ том же JSON, если есть что поставить: ${fields.join(", ")}.` : "";
  return PLAN_SYSTEM.replace("\n\nОтвет — только JSON:\n", `${story}${graphics}\n\nОтвет — только JSON:\n`) + tail;
}

/** Отрезки ролика, где кадр тёмный, секунды. */
function darkRanges(c: ClipInfo): [number, number][] {
  const out: [number, number][] = [];
  (c.brightness ?? []).forEach((v, i) => {
    if (v >= DARK) return;
    const t = i / 2;
    const last = out[out.length - 1];
    if (last && t - last[1] <= 0.5) last[1] = t + 0.5;
    else out.push([t, t + 0.5]);
  });
  return out;
}

const clipBrief = (c: ClipInfo) => {
  const dark = darkRanges(c).map(([a, b]) => `${a}–${b}`).join(", ") || "нет";
  const speech = c.transcript.phrases.map((p) => `    [${p.s}–${p.e}] ${p.text}`).join("\n") || "    (речи нет)";
  const moments = c.moments.map((m) => `    [${m.from}–${m.to}] ${m.shows}${m.text ? ` | надпись «${m.text}» (${m.textZone})` : ""}${m.speaking ? " | говорит" : ""}`).join("\n") || "    (описания нет)";
  return `${c.key}${c.still ? " (картинка — планом под слова автора, один раз, от 3 с)" : ""}: ${c.duration.toFixed(1)} с, ${c.views ?? "?"} просмотров, ${c.date ?? "дата ?"}, язык речи ${c.transcript.language}. ${c.shows}\n  Тёмные места (не ставить в кадр): ${dark}\n  Склейки (смена плана), с: ${c.cuts?.length ? c.cuts.join(", ") : c.still ? "картинка" : "нет данных"}\n  Речь:\n${speech}\n  Что видно:\n${moments}`;
};

/** Ошибки черновика, понятные модели: она их исправляет со второй попытки. */
/**
 * Начало зачина — первые три слова, «вот этот/эта/эти» не различаются: «Вот эта кореянка» и «Вот этот кореец» — разные,
 * «Вот этот парень» и «Вот эти парни» — тоже. \b в JS не видит кириллицу, поэтому границы — пробелы. Продолжение
 * начинается «Помните вот этого/эту…» — «помните» в сравнении не участвует.
 */
const opening = (text: string) => splitWords(text.toLowerCase().replace(/[«»"",.!?:;]/g, "")).filter((w, i) => i > 0 || w !== "помните").slice(0, 3).join(" ").replace(/^вот (эта|эти|это|этого|эту|этих) /, "вот этот ");

/**
 * Обороты, которые уже звучали в зацепках канала: пары соседних слов (по корню — первые 5 букв), что есть хотя бы в двух
 * из последних восьми зацепок и в новой. «вот этот» — приём автора, он оборотом не считается.
 */
function hookTemplates(text: string, recent: string[]): { phrase: string; times: number }[] {
  const pairs = (t: string) => {
    const w = plainWords(t).filter((x) => !["вот", "этот", "эта", "эти", "это", "тот", "та", "те", "и", "а", "в", "на", "с", "не"].includes(x));
    return new Map(w.slice(1).map((x, k) => [`${w[k].slice(0, 5)} ${x.slice(0, 5)}`, `${w[k]} ${x}`]));
  };
  const counts = new Map<string, number>();
  for (const h of recent.slice(0, 8)) for (const key of pairs(h).keys()) counts.set(key, (counts.get(key) ?? 0) + 1);
  const found = [...pairs(text)].filter(([key]) => (counts.get(key) ?? 0) >= 2).map(([key, phrase]) => ({ phrase, times: counts.get(key)! }));
  // «знает каждый», «помнят все», «видел весь интернет», «сидит в голове у всех» — один оборот разными словами
  const knows = /(знает|знают|помнит|помнят|видел|видели|слышал|слышали|в голове)\s+(\S+\s+){0,2}(каждый|все|всех|весь)/i;
  const knew = recent.slice(0, 8).filter((h) => knows.test(h)).length;
  const m = text.match(knows);
  if (m && knew) found.push({ phrase: `${m[0]}» — «это все знают`, times: knew });
  return found;
}

/** Ролики героя только с тем, что в ролике прозвучит его голосом: речь внутри кусков orig. */
function heardInPieces(d: Draft, clips: ClipInfo[]): ClipInfo[] {
  const used = d.segments.flatMap((s) => (s.type === "orig" ? [s] : []));
  return clips
    .map((c) => ({ ...c, transcript: { ...c.transcript, phrases: c.transcript.phrases.filter((p) => used.some((u) => u.clip === c.key && p.e > u.from + 0.1 && p.s < u.to - 0.1)) } }))
    .filter((c) => c.transcript.phrases.length);
}

/** Окно ролика, где в кадре пусто (между людьми, одни руки, срезанные головы) — по разбору кадров. */
const emptyWindow = (c: ClipInfo, from: number, to: number) => {
  const inside = c.moments.filter((m) => m.to > from + 0.05 && m.from < to - 0.05);
  return inside.length > 0 && inside.filter((m) => m.empty).reduce((a, m) => a + Math.min(m.to, to) - Math.max(m.from, from), 0) >= (to - from) * 0.5;
};

const plainWords = (text: string) => text.toLowerCase().replace(/ё/g, "е").replace(/[^a-zа-я0-9\s]/g, " ").split(/\s+/).filter(Boolean);

/**
 * Цитаты автора, которые звучат в роликах героя: «Женя? Ты гений. Укуси тебя пчела» — это должен сказать сам герой
 * куском, а не голос автора (29.10, Копатыч). Совпадение — три слова подряд из цитаты в «…» есть в расшифровке ролика.
 */
function quotedFromClips(text: string, clips: ClipInfo[]): { quote: string; clip: string; at: number } | null {
  // в кавычках — от трёх слов подряд; пересказ без кавычек («он ответил: кто не подписался, тот заминирован», 30.10
  // «Тапок») — от четырёх
  const parts: [string, number][] = [...[...text.matchAll(/«([^»]+)»/g)].map((m) => [m[1], 3] as [string, number]), [text.replace(/«[^»]*»/g, " "), 4]];
  for (const [part, need] of parts) {
    const q = plainWords(part);
    if (q.length < need) continue;
    for (const c of clips) {
      for (const ph of c.transcript.phrases) {
        const said = ` ${plainWords(ph.text).join(" ")} `;
        for (let i = 0; i + need <= q.length; i++) if (said.includes(` ${q.slice(i, i + need).join(" ")} `)) return { quote: q.slice(i, i + need).join(" "), clip: c.key, at: ph.s };
      }
    }
  }
  return null;
}

export function checkDraft(d: Draft, clips: ClipInfo[], recentHooks: string[] = [], recentMemes: string[] = [], chosenHook?: string): string[] {
  const errors: string[] = [];
  const byKey = new Map(clips.map((c) => [c.key, c]));
  const lines = new Map([...d.narration, ...d.heroLines].map((l) => [l.id, l.text]));
  const words = (id: string) => splitWords(lines.get(id) ?? "").length;
  if (!d.segments?.length) return ["нет ни одного куска"];
  if (d.segments[0].type !== "narr") errors.push("первый кусок должен быть голосом автора");
  const first = d.segments[0];
  if (first.type === "narr" && words(first.line) > 16) errors.push(`зацепка ${first.line} длиннее 16 слов`);
  const hook = first.type === "narr" ? opening(lines.get(first.line) ?? "") : "";
  const same = hook ? recentHooks.find((h) => opening(h) === hook) : undefined;
  if (same) errors.push(`зацепка начинается так же, как прошлый ролик («${same.slice(0, 40)}…») — начни иначе`);
  const firstText = first.type === "narr" ? lines.get(first.line) ?? "" : "";
  // один оборот на весь канал («знает каждый», «помнят все» — в 6 роликах Exile подряд, владелец 30.10)
  for (const t of hookTemplates(firstText, recentHooks)) errors.push(`зацепка повторяет оборот «${t.phrase}» из ${t.times} последних роликов канала — построй фразу по-другому`);
  if (chosenHook && plainWords(firstText).join(" ") !== plainWords(chosenHook).join(" ")) errors.push(`первая реплика автора — выбранная зацепка слово в слово: «${chosenHook}»`);
  // фраза, которую через секунду скажет сам герой, в зачине звучит дважды (Виталя, Литвинков 30.10)
  const echo = firstText ? quotedFromClips(firstText, heardInPieces(d, clips)) : null;
  if (echo) errors.push(`зацепка произносит «${echo.quote}», а это звучит голосом героя в ${echo.clip} около ${echo.at.toFixed(1)} с — назови мем по-другому («тот самый мем про чай»), а фраза пусть прозвучит его голосом`);
  // один ролик подряд: куски героя и планы автора из одного ролика, идущие друг за другом
  let run = { clip: "", seconds: 0 };
  for (const s of d.segments) {
    // видеомем и кусок героя сами меняют картинку: рассказ героя идёт целиком (владелец 30.10, Язь), длинный план монтаж
    // оживляет наездом (cuts.ts punchIns) — у героини с одним 70-секундным разговором раскладка иначе не сходилась (31.10, Круз)
    if (s.type !== "narr") {
      run = { clip: "", seconds: 0 };
      continue;
    }
    const parts: [string, number][] = (s.shots ?? []).map((sh, k, all) => [sh.still?.clip ?? sh.clip ?? "", ((all[k + 1]?.word ?? words(s.line)) - sh.word) / 3.2]);
    // вставка-картинка внутри куска тоже разбивает ролик
    const broken = (d.inserts ?? []).some((x) => x.line === s.line);
    for (const [clip, sec] of parts) {
      run = clip && clip === run.clip ? { clip, seconds: run.seconds + sec } : { clip, seconds: sec };
      if (run.seconds > 13) {
        errors.push(`ролик ${clip} идёт подряд ${Math.round(run.seconds)} с — разбей его другим роликом или вставкой`);
        run = { clip: "", seconds: 0 };
      }
    }
    if (broken) run = { clip: "", seconds: 0 };
  }
  // pointer: на зачине (автор поднимается снизу с первым словом), под ним — ролик самого героя
  const pseg = d.pointer && first.type === "narr" && first.line === d.pointer.line ? first : undefined;
  if (!d.pointer || !pseg) errors.push("нет pointer на зацепке — отметь её реплику, word 0, и кто герой на кадре");
  else {
    const shot = (pseg.shots ?? []).find((x) => x.word === 0);
    if (!shot?.clip || shot.still || shot.phone) errors.push(`первый план ${pseg.line} должен быть роликом героя, а не стоп-кадром или телефоном: зритель сразу видит героя`);
    // первую секунду плана закрывает зелёная заставка: короткий первый план уходил под неё целиком (30.10, Язь)
    const change = (pseg.shots ?? []).filter((x) => x.word > 0).map((x) => x.word).sort((a, b) => a - b)[0];
    if (change !== undefined && change < Math.min(8, words(pseg.line))) errors.push(`первый план ${pseg.line} сменяется на слове ${change} — держи его до 8-го слова: первую секунду его закрывает заставка`);
    if (!d.pointer.target?.trim()) errors.push("в pointer нет target — кто герой на первом кадре");
  }
  let seconds = 0;
  let heroSeconds = 0;
  const vmemes = new Map(videoMemeCatalog().map((v) => [v.id, v]));
  for (const [i, s] of d.segments.entries()) {
    if (s.type === "vmeme") {
      const v = vmemes.get(s.meme);
      if (!v) errors.push(`кусок ${i}: видеомема «${s.meme}» нет в списке — возьми id из списка видеомемов`);
      else if (v.retired) errors.push(`кусок ${i}: видеомем «${s.meme}» устарел — возьми свежий той же реакции из списка видеомемов`);
      else if (recentMemes.includes(s.meme)) errors.push(`кусок ${i}: видеомем «${s.meme}» был в последних роликах — возьми другой той же реакции`);
      else if (on("contentId") && v.contentId === "high") errors.push(`кусок ${i}: видеомем «${s.meme}» держится на чужой музыке (${v.contentIdWhy ?? "Content ID"}) — возьми мем с репликой той же реакции`);
      if (seconds < 5) errors.push(`кусок ${i}: видеомем в первые 5 секунд — зритель ещё не знает, на что реагировать`);
      const prev = d.segments[i - 1];
      const next = d.segments[i + 1];
      if (!next) errors.push(`кусок ${i}: видеомем последним куском — ролик кончается на герое или авторе`);
      else if (prev?.type === "narr" && /:\s*$/.test(lines.get(prev.line) ?? "") && next.type !== "narr") errors.push(`кусок ${i}: видеомем стоит между подводкой автора и словами героя — поставь его после куска героя`);
      seconds += v?.duration ?? 2;
      continue;
    }
    if (s.type === "narr") {
      if (!lines.has(s.line)) errors.push(`кусок ${i}: нет текста ${s.line}`);
      const n = words(s.line);
      seconds += n / 3.2;
      // автор читает снимок (комментарий бренда, пост) — это слова героев истории, их время идёт в долю героя (31.10,
      // стажёры: десять комментариев вслух не сходились с «герой от 25%»)
      for (const [k, sh] of (s.shots ?? []).entries()) {
        if (byKey.get(sh.still?.clip ?? sh.clip ?? "")?.still) heroSeconds += (((s.shots ?? [])[k + 1]?.word ?? n) - sh.word) / 3.2;
      }
      // кусок зацепки проверен выше; остальные — связки, главное говорит герой
      if (s !== first && n > 26) errors.push(`кусок ${i} (${s.line}): ${n} слов — сократи до 22 или дай это сказать герою его куском`);
      // связка без факта («И вот итог:», «Это был он.») зрителю ничего не сообщает (владелец 30.10 о Копатыче: «с 35 по 43
      // вообще не понятно зачем там»)
      if (s !== first && n > 0 && plainWords(lines.get(s.line) ?? "").every((w) => EMPTY_WORDS.has(w))) errors.push(`кусок ${i} (${s.line}): «${lines.get(s.line)}» ничего не сообщает зрителю — скажи, что случилось или кто это, и этим подведи к следующему куску`);
      // штампы текста автора (по проверке закадра video-recap-skills, 31.10): «это не просто X, а Y» звучит как реклама,
      // тире голос читает лишней паузой (правило «вместо тире — запятые» есть и выше)
      if (on("storyPlan") && s !== first) {
        const said = lines.get(s.line) ?? "";
        if (/(^|[\s,])не (просто|только лишь)\s[^.!?]{0,60},\s*а\s/i.test(said)) errors.push(`кусок ${i} (${s.line}): оборот «не просто…, а…» — скажи прямо, что случилось («Вазелин переименовался ради неё»)`);
        if (/\s[—–]\s/.test(said)) errors.push(`кусок ${i} (${s.line}): тире в тексте автора — поставь запятую или точку`);
      }
      // зачин называет мем его же фразой («„Укуси меня пчела“ знает каждый») — это якорь, а не пересказ
      const quoted = s === first ? null : quotedFromClips(lines.get(s.line) ?? "", clips);
      if (quoted) errors.push(`кусок ${i} (${s.line}): автор цитирует «${quoted.quote}», а это звучит в ${quoted.clip} около ${quoted.at.toFixed(1)} с — поставь туда кусок героя с этой фразой его голосом, а у автора её убери`);
      if (!s.shots?.length || s.shots[0].word !== 0) errors.push(`кусок ${i}: первый план должен начинаться со слова 0`);
      for (const sh of s.shots ?? []) {
        if (sh.word < 0 || sh.word >= n) errors.push(`кусок ${i}: план на слове ${sh.word}, а слов ${n}`);
        const key = sh.still?.clip ?? sh.clip;
        const clip = key ? byKey.get(key) : undefined;
        if (!clip) errors.push(`кусок ${i}: нет ролика ${key}`);
        const at = sh.still?.at ?? sh.at ?? 0;
        if (clip && (at < 0 || at > clip.duration - 0.3)) errors.push(`кусок ${i}: ${key} at=${at} за пределами ролика (${clip.duration.toFixed(1)} с)`);
        // окно плана по расчётному темпу: от его слова до слова следующего плана
        const next = (s.shots ?? []).find((x) => x.word > sh.word)?.word ?? n;
        const length = sh.still ? 0.5 : Math.max(0.8, (next - sh.word) / 3.2);
        // картинка (пост, скриншот) тёмной не бывает: тёмная тема TikTok у комментариев брендов — это и есть кадр (31.10)
        if (clip && !clip.still && windowBrightness(clip, at, at + length) < DARK) errors.push(`кусок ${i}: план ${key} с ${at} с — тёмный кадр, возьми светлый`);
        else if (clip && !sh.still && emptyWindow(clip, at, at + length)) errors.push(`кусок ${i}: план ${key} с ${at} с — в кадре пусто (между людьми, руки, срезанные головы или картинка), возьми кадр, где виден человек или главное`);
      }
    } else {
      const clip = byKey.get(s.clip);
      if (!clip) errors.push(`кусок ${i}: нет ролика ${s.clip}`);
      // пост читает автор своим голосом (владелец 30.10: «озвучивать посты не нужно… моим голосом озвучка должна быть»)
      else if (clip.still) errors.push(`кусок ${i}: ${s.clip} — картинка (пост), голосом героя её не читают: поставь её планом под слова автора, и главное из неё скажет автор`);
      else if (s.from < 0 || s.to > clip.duration + 0.05 || s.to - s.from < 1.5) errors.push(`кусок ${i}: ${s.clip} ${s.from}–${s.to} вне ролика (${clip.duration.toFixed(1)} с) или короче 1,5 с`);
      else if (windowBrightness(clip, s.from, s.to) < DARK) errors.push(`кусок ${i}: ${s.clip} ${s.from}–${s.to} тёмный — возьми светлый кусок`);
      else if (emptyWindow(clip, s.from, s.to)) errors.push(`кусок ${i}: ${s.clip} ${s.from}–${s.to} — в кадре пусто больше половины куска, возьми другой кусок`);
      // длинный план монтаж оживляет наездом на говорящего (montage.ts punchIns); чужие перебивки ради смены картинки
      // владелец отверг (30.10, Копатыч: «лишний кадр, который резко меняется», Болото: «показывают 3 других людей»)
      if (s.type === "orig")
        for (const c of s.covers ?? []) {
          const src = byKey.get(c.clip);
          if (!(c.from >= s.from - 0.05 && c.to <= s.to + 0.3 && c.to - c.from >= 0.8 && c.to - c.from <= 3.5)) errors.push(`кусок ${i}: перекрытие ${c.from}–${c.to} — внутри куска ${s.from}–${s.to}, от 1 до 3,5 с`);
          else if (!src || c.at < 0 || c.at + (c.to - c.from) > src.duration + 0.05) errors.push(`кусок ${i}: перекрытие планом ${c.clip} с ${c.at} с — вне ролика`);
          else if (windowBrightness(src, c.at, c.at + c.to - c.from) < DARK || emptyWindow(src, c.at, c.at + c.to - c.from)) errors.push(`кусок ${i}: перекрытие планом ${c.clip} с ${c.at} с — тёмный или пустой кадр, возьми другой`);
          // говорящего в кадре не закрывают: на 32 с Копатыча перебивка закрыла «Женя, ты гений, укуси тебя пчела»
          else if (clip?.moments.some((m) => m.speaking && !m.empty && m.to > c.from + 0.3 && m.from < c.to - 0.3)) errors.push(`кусок ${i}: перекрытие ${c.from}–${c.to} закрывает того, кто говорит в ${s.clip}, — зритель смотрит на говорящего; убери это перекрытие`);
        }
      // осмысленная речь на чужом языке звучит переводом: «I'm here to save Brooklyn» без перевода русский зритель не
      // поймёт (2.11, Спид: главная фраза ролика шла куском orig по-английски)
      if (s.type === "orig" && clip && clip.transcript.language !== "ru") {
        const said = clip.transcript.phrases.filter((p) => p.s >= s.from - 0.3 && p.e <= s.to + 0.3).map((p) => p.text).join(" ");
        if (splitWords(said).length >= 8) errors.push(`кусок ${i}: ${s.clip} ${s.from}–${s.to} — речь по-${clip.transcript.language === "en" ? "английски" : "иностранному"} («${said.slice(0, 80)}»): сделай его dub с переводом на начало каждой фразы`);
      }
      seconds += s.to - s.from;
      heroSeconds += s.to - s.from;
      if (s.type === "dub") for (const l of s.lines ?? []) if (!lines.has(l.line)) errors.push(`кусок ${i}: нет перевода ${l.line}`);
    }
  }
  // картинка (пост, скриншот) — один раз и не меньше 3 секунд (30.10, Binance: посты мелькали по кругу и «выходили как новые»)
  const stills = new Map<string, { uses: number; short: boolean }>();
  for (const s of d.segments) {
    if (s.type !== "narr") continue;
    for (const [k, sh] of (s.shots ?? []).entries()) {
      const key = sh.still?.clip ?? sh.clip;
      if (!key || !byKey.get(key)?.still) continue;
      const next = (s.shots ?? [])[k + 1]?.word ?? words(s.line);
      const e = stills.get(key) ?? { uses: 0, short: false };
      // идёт дальше на следующей фразе тем же планом — это не новый показ
      e.uses++;
      if ((next - sh.word) / 3.2 < readSeconds(byKey.get(key)!) && k + 1 < (s.shots ?? []).length) e.short = true;
      stills.set(key, e);
    }
  }
  // снимки (посты, комментарии) — ради них история: каждый показан на своей фразе (владелец 31.10 о стажёрах: «нужно было
  // показать комментарии брендов всех» — из трёх снимков режиссёр взял один, в самом конце)
  // у поста с картинками снимков несколько (карточка и сами картинки, story.ts postStills) — показан один, и пост показан
  // (3.11: пост Cointelegraph про Bitget дал c5–c7, и заготовка упала на «c6, c7 не показаны»)
  const shownPosts = new Set(clips.filter((c) => stills.has(c.key)).map((c) => c.url));
  const unshownPosts = new Map<string, string[]>();
  for (const c of clips) if (c.still && !shownPosts.has(c.url)) unshownPosts.set(c.url, [...(unshownPosts.get(c.url) ?? []), c.key]);
  const unshown = [...unshownPosts.values()].map((keys) => (keys.length > 1 ? `одна из ${keys.join(", ")}` : keys[0]));
  if (unshown.length) errors.push(`картинки ${unshown.join("; ")} не показаны — это снимки, ради которых история (посты, комментарии): поставь каждую планом под слова автора на фразе, где о ней речь (из снимков одного поста хватит одного)`);
  for (const [key, e] of stills) {
    if (e.uses > 1) errors.push(`картинка ${key} показана ${e.uses} раза — покажи её один раз, на фразе, где о ней говорят, и держи до конца фразы`);
    if (e.short) errors.push(`картинка ${key} держится меньше ${readSeconds(byKey.get(key)!).toFixed(1)} с — дай её прочитать: план до конца фразы`);
  }
  if (seconds < 31 || seconds > 46) errors.push(`по расчёту ролик ${Math.round(seconds)} с, а нужно 35–42`);
  // владелец 29.10: «очень много озвучки моей, хотя можно, чтобы в видео сказали» — если героя есть что послушать,
  // он звучит не меньше 40% ролика
  const speech = clips.reduce((sum, c) => sum + c.transcript.phrases.reduce((a, p) => a + (p.e - p.s), 0), 0);
  // в истории из одних постов и скриншотов (Binance, 30.10) говорить герою нечего — доли нет
  // со снимками (посты, комментарии брендов) часть ролика — они под словами автора: герою хватает четверти (31.10, стажёры:
  // «покажи все снимки» и «герой от 40%» не сходились)
  const shots = clips.filter((c) => c.still).length;
  const need = speech >= 20 && shots < 2 ? 0.4 : speech >= 5 ? 0.25 : 0;
  if (seconds > 0 && heroSeconds / seconds < need) errors.push(`герой звучит ${Math.round((heroSeconds / seconds) * 100)}% ролика, а нужно от ${Math.round(need * 100)}%: отдай ему главные фразы его же голосом, а слова автора сократи`);
  const known = new Set(memeCatalog().map((m) => m.id));
  const videoCount = d.segments.filter((s) => s.type === "vmeme").length;
  if ((d.memes ?? []).length + videoCount > 3) errors.push(`мемов ${(d.memes ?? []).length + videoCount} (картинки и видео), а нужно 2–3`);
  // владелец 4.11: «используй почаще фото мемы, видеомемы только в определённых уверенных сценах» — видеомем не обязателен
  if (videoCount > 1) errors.push(`видеомемов ${videoCount}, а нужно не больше одного — остальные реакции картинками-мемами`);
  for (const m of d.memes ?? []) {
    if (!known.has(m.meme)) errors.push(`мема «${m.meme}» нет в списке — возьми id из списка`);
    else if (recentMemes.includes(m.meme)) errors.push(`мем «${m.meme}» был в последних роликах — возьми другой из той же реакции`);
    if (!lines.has(m.line) || m.word >= words(m.line)) errors.push(`мем ${m.line}:${m.word} не на слове`);
  }
  if ((d.people ?? []).length > 2) errors.push(`знаменитостей (people) ${d.people!.length}, а нужно 0–2`);
  for (const p of d.people ?? []) {
    if (!lines.has(p.line) || p.word >= words(p.line)) errors.push(`people ${p.line}:${p.word} не на слове`);
    if (!p.name?.trim()) errors.push(`в people ${p.line}:${p.word} нет name — статьи в английской Википедии`);
  }
  for (const x of d.inserts ?? []) if (!lines.has(x.line) || x.word >= words(x.line) || !x.picture?.trim()) errors.push(`вставка ${x.line}:${x.word} не на слове или без картинки`);
  if ((d.logos ?? []).length > 8) errors.push(`логотипов ${d.logos!.length}, а нужно до 8`);
  for (const x of d.logos ?? []) if (!lines.has(x.line) || x.word >= words(x.line) || !/^[a-z0-9-]+(\.[a-z0-9-]+)+$/i.test(x.domain?.trim() ?? "")) errors.push(`логотип ${x.brand ?? "?"} ${x.line}:${x.word} не на слове или без сайта (domain вроде duolingo.com)`);
  for (const a of d.accents ?? []) if (!lines.has(a.line) || a.word >= words(a.line)) errors.push(`акцент ${a.line}:${a.word} не на слове`);
  // последний кусок героя договаривает мысль: если сразу за ним, без паузы, идёт её продолжение («Хотя она и не
  // выступала у нас, зато передала свой подарок»), ролик звучит оборванным (владелец 1.11 о Шакире: «конец будто оборван»)
  const tail = [...d.segments].reverse().find((s) => s.type === "orig" || s.type === "dub");
  if (tail && (tail.type === "orig" || tail.type === "dub") && d.segments.indexOf(tail) >= d.segments.length - 2) {
    const c = clips.find((x) => x.key === tail.clip);
    const next = c?.transcript.phrases.find((p) => p.s >= tail.to - 0.3);
    const prev = c?.transcript.phrases.filter((p) => p.e <= tail.to + 0.3).pop();
    if (next && prev && next.s - prev.e < 0.7 && next.e - tail.from <= 14 && (CONTINUES.test(next.text) || !/[.!?…]$/.test(prev.text.trim()))) {
      errors.push(`последний кусок героя ${tail.clip} обрывает мысль: сразу за ним она продолжается — «${next.text.slice(0, 80)}» (${next.s.toFixed(1)}–${next.e.toFixed(1)} с); кончи кусок на ${(next.e + 0.25).toFixed(1)} с`);
    }
  }
  return errors;
}

/** Фраза продолжает предыдущую: «Хотя…», «Но…», «Зато…», «Потому что…». */
const CONTINUES = /^(хотя|но|а|зато|потому|поэтому|и|так что|правда|ведь|though|but|and|because|so)(?=[\s,.!?…]|$)/i;

/** recentHooks — первые фразы последних роликов канала: новое начало на них не похоже. */
/** Каталог мемов владельца (news/memes/memes.json): id, название и ситуация, для которой мем. */
export function memeCatalog(): { id: string; file: string; name: string; situation: string; example?: string; emotion?: string }[] {
  const file = path.join(MEDIA_ROOT, "memes", "memes.json");
  if (!fs.existsSync(file)) return [];
  const list = readJson<{ memes?: { id: string; file: string; name: string; situation: string; example?: string; emotion?: string }[] }>(file).memes ?? [];
  return list.filter((m) => fs.existsSync(path.join(MEDIA_ROOT, "memes", m.file)));
}

/**
 * contentId "high" — шутка держится на чужой музыке (тема «Умерь свой энтузиазм», «Ералаш»): по каталогу мемов
 * agent-video-editor такую запись Content ID ловит надёжнее всего, и доход ролика уходит правообладателю (31.10).
 */
export type VideoMeme = { id: string; file: string; name: string; says: string; situation: string; example?: string; emotion?: string; duration: number; contentId?: "high" | "medium" | "low"; contentIdWhy?: string; crop?: string; cut?: string; size?: [number, number]; whole?: boolean; transition?: boolean; retired?: boolean; year?: number };

/** Видеомемы владельца (news/memes/video/videos.json): короткие врезки со своим звуком, 1080×1920. */
export function videoMemeCatalog(): VideoMeme[] {
  const dir = path.join(MEDIA_ROOT, "memes", "video");
  const file = path.join(dir, "videos.json");
  if (!fs.existsSync(file)) return [];
  return (readJson<{ videos?: VideoMeme[] }>(file).videos ?? []).filter((v) => v.duration > 0 && fs.existsSync(path.join(dir, v.file)));
}

/** Слова связки без факта: реплика автора только из них зрителю ничего не сообщает. */
const EMPTY_WORDS = new Set(["и", "а", "но", "вот", "тут", "тогда", "потом", "дальше", "далее", "самое", "интересное", "главное", "итог", "итоги", "голосование", "результат", "это", "был", "была", "были", "было", "он", "она", "они", "так", "что", "же", "ну", "в", "на", "все", "всё", "вышло", "случилось", "смотрите"].map((w) => w.replace(/ё/g, "е")));

/** Каталог видеомемов для задания: по реакциям — id, что звучит, когда уместен. */
function videoMemeList() {
  // владелец 10.11: «видеомемы не используй вообще» — список пуст, режиссёр кусков vmeme не ставит (выключатель "videoMemes")
  if (!on("videoMemes")) return "";
  const groups = new Map<string, string[]>();
  for (const v of videoMemeCatalog()) {
    // мемы на чужой музыке режиссёру не предлагаются; в старых роликах они остаются (монтаж берёт весь каталог)
    if (on("contentId") && v.contentId === "high") continue;
    // классика 2006–2016 устарела (владелец 4.11: «очень старые и не актуальные + долгие»): в каталоге — для перемонтажа старых роликов
    if (v.retired) continue;
    const g = v.emotion ?? "другое";
    groups.set(g, [...(groups.get(g) ?? []), `  - ${v.id} — ${v.name}, ${v.duration.toFixed(1)} с, звучит: ${v.says}. Когда: ${v.situation}`]);
  }
  return [...groups].map(([g, list]) => `Реакция «${g}»:\n${list.join("\n")}`).join("\n");
}

/**
 * Сколько держать снимок, чтобы его прочитали: по словам его текста (разбор кадров пишет текст в moments), от 1,5 до 3 с.
 * Короткий комментарий бренда («I can't drive») держался по 3 с, и десять комментариев не влезали в ролик (31.10, стажёры).
 */
function readSeconds(c: ClipInfo): number {
  // снимок одного комментария: читают сам комментарий (он в описании в «»), а не шапку «Комментарии: 378.3K… Ответить»
  const quoted = /комментари/i.test(`${c.title} ${c.shows}`) ? c.shows.match(/«([^»]+)»/)?.[1] : undefined;
  const text = quoted ?? c.moments.map((m) => m.text ?? "").join(" ");
  const n = text.split(/\s+/).filter(Boolean).length;
  return n ? Math.min(3, Math.max(1.5, n / 2.5)) : 3;
}

/** Каталог мемов для задания: по реакциям, у каждой — её мемы с ситуацией. */
function memeList() {
  const groups = new Map<string, string[]>();
  for (const m of memeCatalog()) {
    const g = m.emotion ?? "другое";
    groups.set(g, [...(groups.get(g) ?? []), `  - ${m.id} — ${m.name}: ${m.situation}`]);
  }
  return [...groups].map(([g, list]) => `Реакция «${g}»:\n${list.join("\n")}`).join("\n");
}

const CONTEXT_SYSTEM = `Ты редактор, который проверяет сценарий короткого ролика перед монтажом. Перед тобой ролик по порядку: слова автора и куски героя со звуком оригинала — расшифровка куска, что звучало прямо перед ним и кто в кадре. Кусок 0 — зацепка: её выбрал другой редактор, она остаётся слово в слово и нарочно начинает с самого невероятного, раньше объяснений; завязка звучит сразу за ней. Поэтому о куске 0 замечаний не пиши — если зрителю не хватает завязки, предложи её в следующих кусках. Посмотри глазами зрителя, который не видел оригинала:
- каждый кусок героя понятен сам: если реплика отвечает на вопрос, вопрос звучит в этом же куске оригинальными голосами или автор передаёт его точно — кто спросил и о чём;
- зритель понимает завязку до первой реплики героя: кто эти люди и что за игра или ситуация («на сцену вышли пятеро, один из них — настоящий голос Копатыча»), иначе «они не будут говорить» звучит ни о ком;
- люди названы так, как их можно узнать по фактам и расшифровке; кто задал вопрос, автор говорит, только если имя звучит в расшифровке или стоит в фактах — человек в кадре не обязательно говорящий. Если автор подписывает следующий кусок («ведущий Эксайл придумал:», «спросил Эксайл:»), сверь с описанием ролика ниже: там сказано, кто говорит; «игроки», «кто-то» или без имени — значит, автор подписал наугад;
- смысл реплики тот же, что в оригинале: подсказка в игре — это подсказка, шутка — шутка, вопрос ведущего — вопрос ведущего;
- у автора только то, что есть в фактах и расшифровке, и он не пересказывает то, что герой сам говорит в своих кусках или рядом с ними: смешную фразу зритель слышит голосом героя;
- то, что автор рассказывает своими словами, но в роликах героя звучит голосом (ниже — что в роликах не вошло в куски), особенно развязка — кто победил, кто под маской, чем кончилось, — звучит куском героя: назови ролик и секунды, откуда его взять;
- зритель видит только этот ролик, выпуска он не смотрел: всё, на что ссылается автор, — вопрос, на который отвечают, правило игры, чужие ответы, ставки игроков, прозвище, номер — он уже увидел или услышал раньше в ролике. «Номер четыре выдал „2К16“, и на него поставили почти все» без куска, где всех спрашивают год и все отвечают «2016», непонятно: назови, какой кусок поставить перед этим;
- в игре на угадывание (кто из пятерых настоящий, кто под маской) ответ не звучит и не показывается до раскрытия: если зацепка или автор раньше времени выделяют героя («а вот этот мужчина — голос Копатыча»), игроки потом угадывают то, что зритель уже знает;
- начатый рассказ героя досказан его голосом: если между двумя кусками одного ролика пропущена середина его рассказа (она есть ниже, в «что ещё звучит»), а вместо неё говорит автор, назови секунды, которые вернуть, и что убрать вокруг ради длины;
- если история про мем или вирусный ролик, сам мем звучит и виден в ролике: если его нет в кусках, а он есть в роликах героя (ниже, в «что ещё звучит» или в описаниях), назови ролик и секунды;
- в ролике есть главное из заголовка и пересказа истории (лучше голосом героя): если история «на болото его привезла мама», а про маму в ролике ни слова, — назови кусок, откуда это взять, и что убрать ради длины;
- под словами автора видно то, о чём он говорит (у каждой реплики автора — «под словами»: какой план под какими словами и что на нём): если он говорит о событии — «повалил монстра и крикнул», «репост набрал миллионы», «ответил в чате», — а под словами другое, назови ролик и секунды, где это видно; если этого нет ни в одном ролике, предложи сказать о том, что зритель видит, и убрать подробности, которые не показать;
- человек, о котором автор говорит впервые, назван так, чтобы зритель понял, кто он и при чём тут («стример Cuffem, друг Спида» — а если он для истории не важен, лучше без него); герой, который отвечает «это неправда», отвечает на слух или догадку, которую зритель уже услышал;
- каждая реплика автора что-то сообщает: связка вроде «И вот итог:», «А дальше самое интересное:» — пустая, вместо неё нужен факт;
- ролик кончается на развязке этой истории или её последствии — после разгадки, признания, коронной фразы; побочная реплика (кто сколько набрал баллов, «спасибо, до свидания») концом не годится, если в роликах есть сильнее. Если сильная реплика героя уже прозвучала («поэтому восторг такой»), хвост автора с мелким новым фактом после неё («а сейчас он чаще ходит на охоту») конец гасит — ролик кончается на герое. Лучший конец — коронная фраза героя, если в роликах она звучит ещё раз на прощание; в игре на угадывание перед ней — одна фраза автора с итогом (кто это был и кто угадал), а побочный факт после раскрытия (кого он ещё озвучивал, «я сразу понял») — не конец.
Ответ — только JSON: {"problems":["кусок N: что не так и как исправить, например: начни кусок героя c5 с 1,5 с — там звучит вопрос"]}; если всё понятно и верно — {"problems":[]}.`;

/** Сценарий для проверки смысла: слова автора и куски героя с тем, что звучало перед ними и кто в кадре. */
function contextBrief(story: Candidate, d: Draft, clips: ClipInfo[]): string {
  const byKey = new Map(clips.map((c) => [c.key, c]));
  const lines = new Map([...d.narration, ...d.heroLines].map((l) => [l.id, l.text]));
  const said = (c: ClipInfo, a: number, b: number) => c.transcript.phrases.filter((p) => p.e > a && p.s < b).map((p) => `[${p.s.toFixed(1)}–${p.e.toFixed(1)}] ${p.text}`).join(" ") || "(речи нет)";
  const vmemes = new Map(videoMemeCatalog().map((v) => [v.id, v]));
  const parts = d.segments.map((s, i) => {
    if (s.type === "narr") {
      // что под словами автора: проверка видит, показан ли тот момент, о котором он говорит (владелец 1.11 о Спиде:
      // «почему не показывают то, что говорится?»)
      const words = splitWords(lines.get(s.line) ?? "");
      const under = s.shots.map((sh) => {
        const k = sh.still?.clip ?? sh.clip;
        const at = sh.still?.at ?? sh.at ?? 0;
        const c = k ? byKey.get(k) : undefined;
        const seen = c?.moments.find((m) => at >= m.from && at < m.to)?.shows ?? c?.shows ?? "?";
        return `«${words.slice(sh.word, sh.word + 3).join(" ")}…» — ${k ?? "?"} ${at} с: ${seen}`;
      });
      return `${i}. АВТОР: «${lines.get(s.line) ?? ""}»${under.length ? `\n   под словами: ${under.join("; ")}` : ""}`;
    }
    if (s.type === "vmeme") return `${i}. ВИДЕОМЕМ: ${vmemes.get(s.meme)?.name ?? s.meme} — звучит: ${vmemes.get(s.meme)?.says ?? "?"}`;
    const c = byKey.get(s.clip);
    if (!c) return `${i}. ГЕРОЙ: ролик ${s.clip}`;
    const seen = c.moments.filter((m) => m.to > s.from && m.from < s.to).map((m) => m.shows).join("; ");
    const own = s.type === "dub" ? `перевод: «${s.lines.map((l) => lines.get(l.line)).join(" ")}», оригинал: ${said(c, s.from, s.to)}` : `звучит: ${said(c, s.from, s.to)}`;
    return `${i}. ГЕРОЙ, ролик ${s.clip} ${s.from}–${s.to} с — ${own}\n   перед куском звучало: ${said(c, Math.max(0, s.from - 10), s.from)}\n   в кадре: ${seen || "?"}`;
  });
  // что звучит в роликах героя мимо кусков: по нему видно, что автор пересказал вместо героя (30.10, «Финал»: победителя
  // объявил автор, хотя в c6 его объявляет ведущий)
  const used = d.segments.flatMap((s) => (s.type === "orig" || s.type === "dub" ? [{ clip: s.clip, from: s.from, to: s.to }] : []));
  const rest = clips
    .map((c) => {
      const left = c.transcript.phrases.filter((p) => !used.some((u) => u.clip === c.key && p.e > u.from + 0.1 && p.s < u.to - 0.1));
      return left.length ? `${c.key}: ${left.map((p) => `[${p.s.toFixed(1)}–${p.e.toFixed(1)}] ${p.text}`).join(" ")}` : "";
    })
    .filter(Boolean);
  // описание роликов с тем, кто что говорит: по нему видно, кого автор подписал под реплику (30.10, Копатыч: «ведущий
  // Эксайл придумал», а предлагали игроки)
  const about = [...new Set(used.map((u) => u.clip))].map((k) => byKey.get(k)).filter((c): c is ClipInfo => !!c).map((c) => `${c.key}: ${c.shows}`);
  // план истории режиссёра: проверка смотрит, отвечает ли конец на главный вопрос (video-recap-skills, 31.10)
  const plan = d.story?.question ? `\nПлан режиссёра: зритель досмотрит, чтобы ${d.story.promise || "узнать развязку"}; главный вопрос — «${d.story.question}»${d.story.withhold ? `; к концу приберегли: ${d.story.withhold}` : ""}. Конец ролика должен на этот вопрос ответить.\n` : "";
  return `История: ${story.title}\n${story.summary}\nФакты:\n${story.facts.map((f) => `- ${f.text}`).join("\n")}\n${plan}\nРолик:\n${parts.join("\n")}\n\nО роликах в кусках — кто что говорит:\n${about.join("\n") || "(нет)"}\n\nЧто ещё звучит в роликах героя (в куски не вошло):\n${rest.join("\n") || "(ничего)"}`;
}

/** Ошибки смысла: вырванная из контекста реплика, неверно названный человек, пересказ мимо оригинала (владелец 29.10, «Фиаско»). */
export async function contextProblems(story: Candidate, d: Draft, clips: ClipInfo[]): Promise<string[]> {
  try {
    const res = await claudeJson<{ problems?: unknown[] }>(CONTEXT_SYSTEM, contextBrief(story, d, clips), { task: "news-context", effort: "medium" });
    return (res.problems ?? []).filter((x): x is string => typeof x === "string" && x.trim().length > 0).slice(0, 6);
  } catch {
    // проверка смысла — подсказка: без неё ролик всё равно собирается
    return [];
  }
}

const HOOK_SYSTEM = `Ты автор канала коротких вертикальных роликов и пишешь их первую фразу — зацепку голосом автора, 9–16 слов, до 5 секунд. Зритель только что открыл ролик и ничего об этой истории не слышал. Фраза рассказывает её с начала, как другу: кто это и что он делал — и сразу то невероятное, ради чего стоит досмотреть. Владелец канала показал, как это звучит: «Вот эта мама удаляла ChatGPT, и он попрощался с ней вот так.» — с первых слов ясно, кто перед нами и что происходит, а как именно попрощался, зритель увидит в ролике. Цитата, деталь или чей-то ответ становятся интересны, когда зритель знает, к чему они: они звучат после завязки, а зацепка эту завязку и даёт.
Знакомое зрителю (бренд, звезда, мем) звучит одним словом внутри фразы — так, как его называют люди: «ChatGPT», «Claude», «Майнкрафт», «Шакира»; что зритель и так знает, не объясняем. «Вот этот», «вот эта» — о человеке, которого зритель в эту секунду видит, то есть о том, кто снят в роликах (они перечислены в задании). Того, кого в роликах нет, зацепка называет тем, кто он: «Бразилец продал всё ради девушки из TikTok, а она оказалась нейросетью.» Если история — происшествие, снятое на видео (нападение, авария, спасение), зацепка звучит прямо над кадрами самого происшествия и говорит, что на них происходит.
Так звучат хорошие зацепки:
- «Вот эта мама удаляла ChatGPT, и он попрощался с ней вот так.»
- «Майнкрафт впервые за семнадцать лет показал то, чего в игре никогда не было.»
- «Этот гость в маске — тот самый мужик, голый на дельфинах.»
- «Вот эта кореянка заставила Вазелин сменить название.»
- «MrBeast из всех стран мира выбрал для путешествия Узбекистан.»
- «Полминуты мужчина бил львицу прутом, чтобы вырвать девочку из её лап.»
Это зачины других историй: из них берётся построение, а слова и цифры — только из фактов этой истории, числа словами. Если история — игра на угадывание (кто из пятерых настоящий, кто под маской), зацепка — загадка, в которой ответа нет: «На сцену вышли пятеро, и только один из них — настоящий голос Копатыча.» Если событие — бренды и компании (пришли в комментарии, ответили, поссорились), зацепка их перечисляет — четыре-пять названий подряд, на каждом в кадре выскочит логотип: «McDonald’s, Duolingo, Red Bull и даже сам TikTok пришли в комментарии к вот этому парню.» Пять вариантов, разных по построению и не похожих на начала последних роликов канала.
Ответ — только JSON: {"hooks":["…","…","…","…","…"]}`;

const HOOK_JUDGE = `Ты редактор ленты коротких роликов. Перед тобой варианты первой фразы одного ролика и начала последних роликов канала. Представь зрителя, который листает ленту и слышит только первые две секунды: на какой фразе он остановится досмотреть? Сильная зацепка — зритель, который ничего об истории не слышал, с первой фразы понимает, кто это и что происходит («Вот эта мама удаляла ChatGPT, и он попрощался с ней вот так»), событие или поворот звучат в первых пяти словах, «вот этот» — о том, кто снят в роликах (они в задании), названия звучат так, как их говорят люди («Claude», а не «ИИ из Claude Code»), зрителю не рассказывают то, что он и так знает, фраза не повторяет оборотов последних роликов канала, и всё в ней — правда по фактам; в игре на угадывание сильная зацепка — загадка, ответ (кто настоящий) в ней не звучит; если событие — бренды и компании, сильнее та, где они перечислены подряд (на каждом выскочит логотип). Оцени каждую от 1 до 10. Ответ — только JSON: {"scores":[8,6],"best":0,"why":"коротко"}, best — номер лучшей с нуля.`;

/**
 * Зацепка до раскладки: пять вариантов, редактор выбирает тот, на котором зритель остановится (владелец 30.10 о Бинансе:
 * «вначале нужно завлекающее… а началось „Бинанс — крупнейшая криптобиржа“, это и так знали все, а то, что взломали, —
 * возможно, даже не узнали и пролистали»). Не вышло — раскладка пишет зацепку сама, как раньше.
 */
export async function pickHook(story: Candidate, sequel: string, recentHooks: string[], hooks: Hooks, clips: ClipInfo[] = []): Promise<string | undefined> {
  const facts = story.facts.map((f) => `- ${f.text}`).join("\n");
  const recent = recentHooks.length ? recentHooks.map((h) => `- «${h}»`).join("\n") : "- (пока нет)";
  // кто снят в роликах: «вот этот» — только о нём (владелец 1.11 о «Фермерше»: «вот этот каменщик», а в кадре его нет)
  const shot = clips.length ? `\n\nРолики в кадре (кого и что видит зритель):\n${clips.map((c) => `- ${c.key}: ${c.shows}`).join("\n")}` : "";
  try {
    await hooks.step("Выбираем зацепку", 40);
    // кому ролик перешлют (оценка редактора, story.ts): зачин, в котором адресат узнаёт своё, пересылают охотнее
    const share = story.rating?.share && !/^некому/i.test(story.rating.share) ? ` Кому зритель это перешлёт: ${story.rating.share}.` : "";
    const asked = await claudeJson<{ hooks?: string[] }>(HOOK_SYSTEM, `История: ${story.title}\n${story.summary}${sequel}\nЧто знакомо зрителю: ${story.rating?.anchor ?? "—"}.${story.rating?.hook ? ` Зачин, с которым историю выбрали: «${story.rating.hook}».` : ""}${share}\nФакты:\n${facts}${shot}\n\nНачала последних роликов канала:\n${recent}`, { task: "news-hook" });
    const options = [...(asked.hooks ?? []), ...(story.rating?.hook && !story.sequelOf ? [story.rating.hook] : [])]
      .map((h) => h.trim())
      .filter((h, i, all) => all.indexOf(h) === i && splitWords(h).length >= 6 && splitWords(h).length <= 16)
      .filter((h) => !hookTemplates(h, recentHooks).length && !recentHooks.some((r) => opening(r) === opening(h)));
    if (!options.length) return undefined;
    const verdict = await claudeJson<{ scores?: number[]; best?: number; why?: string }>(HOOK_JUDGE, `Факты:\n${facts}${shot}\n\nНачала последних роликов канала:\n${recent}\n\nВарианты:\n${options.map((h, i) => `${i}. «${h}»`).join("\n")}`, { task: "news-hook-judge" });
    const best = options[verdict.best ?? 0] ?? options[0];
    hooks.log(`зацепка: «${best}» — оценки ${verdict.scores?.join(", ") ?? "?"}; ${verdict.why ?? ""}`);
    return best;
  } catch (error) {
    hooks.log(`зацепка не выбрана: ${(error as Error).message}`);
    return undefined;
  }
}

/** Замечание проверки смысла о конце ролика: про концовку словами или про один из двух последних кусков. */
function endingProblem(problem: string, segments: number): boolean {
  if (/конц|кончает|финал|развязк|последн/i.test(problem)) return true;
  return [...problem.matchAll(/кусок (\d+)/g)].some((m) => Number(m[1]) >= segments - 2);
}

/**
 * rounds — сколько раз переписывать сценарий по замечаниям проверки смысла (владелец 1.11: «больше 30 минут на 1 ролик
 * неприемлемо» — в ролике South Park 27 минут из 36 ушли на 5 переписываний). По кнопке — 1 раз, без отдельной переписки
 * концовки; в заготовке (prep.ts), где время не ждёт владельца, — 4 и концовка. Раскладка, которая не сходится по
 * правилам (checkDraft), переписывается до 4 раз в любом случае: без неё ролика нет.
 */
/** Подача крипто-историй: часть зрителей в крипте не разбирается, и многим нет 18 — им рассказывают, что случилось. */
const CRYPTO_FUN = `\n\nЭто смешная крипто-история — одна из двух крипто-историй на шесть роликов канала OWNER CRYPTO. Подача — как анекдот, который пересказывают другу: знакомое, абсурдный поворот, мем к месту и финал, над которым смеются. Зритель может не разбираться в крипте: слова крипты звучат так, как их говорят: мемкоин остаётся мемкоином, маркеткап — капитализацией, их не переводят («монета-шутка» владелец отверг 10.11: «это не переводится»); если термин нужно пояснить, это отдельная короткая фраза после него («мемкоин, его любой выпускает за пять минут»). Цифры истории зритель видит: цена и капитализация монеты выезжают числом (numbers) там, где они звучат. Смеёмся над тем, что случилось, а решать, что покупать, оставляем зрителю.`;
const CRYPTO_NEWS = `\n\nЭто крипто-новость — одна из двух крипто-историй на шесть роликов канала OWNER CRYPTO. Подача — короткий выпуск новостей: что случилось, почему это касается обычного человека и его денег, чем кончилось или что будет дальше — по фактам. Зритель может не разбираться в крипте: единственный нужный термин объясни словами из жизни прямо во фразе («биржа — обменник, где хранят и меняют крипту»). Рассказываем о событии, а выводы о курсе и покупках оставляем зрителю.`;
/** Крипто-ролик кончается голосом автора о его телеграм-канале — из самой истории, а не рекламной вставкой. */
const TELEGRAM_ENDING = `\n\nПоследний кусок ролика — фраза автора, которая уводит зрителя в его телеграм-канал (владелец 3.11: «текст про тг нужно озвучивать органично»). Зритель идёт по ссылке, когда слышит причину зайти: что он там увидит и как это связано с тем, что он только что посмотрел. Одна и та же фраза под каждым роликом такой причины не давала: за две недели 965 тысяч просмотров в Инстаграме принесли 32 перехода (разбор 10.11.2026). В канале автор торгует золотом и валютой и показывает каждую свою сделку в реальном времени, без рекламы и продаж. Фраза вырастает из истории одним оборотом, называет это и кончается словами о ссылке в шапке профиля; до 20 слов, без тире. Так это звучит в истории про взлом биржи: «Биржу взломали за ночь, а золото не взломаешь. Свои сделки по нему я показываю в телеграме сразу, как открываю. Ссылка в шапке профиля.» В истории про уход бирж из России: «Биржи уходят, а мои сделки по золоту остаются. Каждую показываю в телеграм-канале в реальном времени, ссылка в шапке профиля.» В истории про хакера, который собирал деньги на обещаниях слива: «Он торговал обещаниями, а я показываю настоящие сделки, по золоту, сразу как открываю. Телеграм-канал в шапке профиля.» В истории про монету, которая обнулилась за сутки: «Монета сгорела за сутки, а золоту пять тысяч лет. Сделки по нему я показываю в телеграме в реальном времени, ссылка в шапке профиля.»`;

/** Последний кусок крипто-ролика — автор говорит о телеграм-канале (TELEGRAM_ENDING). */
function telegramProblems(d: Draft): string[] {
  const last = d.segments[d.segments.length - 1];
  const text = last?.type === "narr" ? d.narration.find((l) => l.id === last.line)?.text ?? "" : "";
  return /телеграм/i.test(text) ? [] : ["Последний кусок ролика — фраза автора о его телеграм-канале со сделками по золоту и ссылкой в шапке профиля, связанная с историей одним оборотом (как в задании)."];
}

export async function writePlan(workDir: string, story: Candidate, clips: ClipInfo[], hooks: Hooks, recentHooks: string[] = [], recentMemes: string[] = [], opts: { rounds?: number; ending?: boolean; trial?: Trial } = {}): Promise<Draft> {
  const rounds = opts.rounds ?? 1;
  const cached = path.join(workDir, "draft.json");
  if (fs.existsSync(cached)) return readJson<Draft>(cached);
  // склейки — для проверки однообразных кусков героя; у разобранных раньше роликов их досчитываем
  await ensureCuts(workDir, clips, hooks.signal);
  const results = await channelResults();
  const liked = results.length ? `\n\nЛучшие ролики канала — их зачины и подача зашли зрителю:\n${resultsBrief(results, 3)}` : "";
  // продолжение начинается с нового поворота, а не с «Помните…»: зачин со знакомого зритель пролистывает (владелец 30.10)
  const sequel = story.sequelOf ? `\n\nЭто продолжение истории, которая уже была на канале: «${story.sequelOf.hook}»${story.sequelOf.views ? ` (${Math.round(story.sequelOf.views / 1000)} тыс. просмотров)` : ""}. Зацепка — то, что случилось дальше: новый поворот звучит в первых словах, а чем всё было в прошлый раз, напомни одной короткой фразой сразу за ней. Так это звучит на другой истории: «Вазелин снова сменил название — теперь ради целой Кореи. Месяц назад он уже переименовался ради одной кореянки.»` : "";
  // крипта — два ролика из шести (story.ts CRYPTO_LANES; владелец 3.11: «1 прикольный смешной, другой новостной формат»)
  const crypto = story.lane === "crypto-fun" ? CRYPTO_FUN : story.lane === "crypto-news" ? CRYPTO_NEWS : "";
  // телеграм в конце крипто-ролика — кроме вариантов опыта на YouTube, где ролик выходит без него (trial.ts)
  const telegram = Boolean(crypto) && speaksTelegram(opts.trial);
  // зачин, с которым историю оценил редактор (story.ts rateCandidates) и выбрал владелец
  const chosen = await pickHook(story, `${sequel}${crypto}`, recentHooks, hooks, clips);
  const check = (d: Draft) => [...checkDraft(d, clips, recentHooks, recentMemes, chosen), ...(telegram ? telegramProblems(d) : [])];
  await hooks.step("Пишем текст и раскладку", 42);
  const pitched = chosen
    ? `\nЗацепка, выбранная редактором (первая реплика автора — она, слово в слово): «${chosen}»`
    : story.rating?.hook && !story.sequelOf
      ? `\nЧто знакомо зрителю: ${story.rating.anchor}. Зачин, с которым историю выбрали: «${story.rating.hook}» — возьми его или сделай сильнее.`
      : "";
  const text = `История: ${story.title}\n${story.summary}${sequel}${pitched}${crypto}${telegram ? TELEGRAM_ENDING : ""}\nГерой: ${story.hero.name} (@${story.hero.handle}, ${story.hero.platform}), ${story.hero.gender === "female" ? "женщина" : "мужчина"}.\nФакты:\n${story.facts.map((f) => `- ${f.text}`).join("\n")}\n\nНачала последних роликов канала (начни иначе):\n${recentHooks.length ? recentHooks.map((h) => `- «${h}»`).join("\n") : "- (пока нет)"}\n\nМемы, которые есть, по реакциям (id — когда уместен):\n${memeList() || "- (мемов нет — memes оставь пустым)"}\n\nВидеомемы, по реакциям (кусок {"type":"vmeme","meme":id}):\n${videoMemeList() || "- (видеомемов нет — кусков vmeme не ставь)"}\n\nМемы последних роликов канала (зритель их уже видел — бери другие):\n${recentMemes.length ? recentMemes.join(", ") : "- (пока нет)"}${liked}\n\nРолики героя:\n${clips.map(clipBrief).join("\n\n")}`;
  // режиссёр смотрит на сами кадры, а не только на их описание: листы разбора, по 0,5 с (владелец 30.10 о Копатыче: на
  // «молодой человек в полосатом» в кадре другой, картинка «Ван Пис» срезана — «просто их не нужно делать»)
  const analysisDir = path.join(workDir, "analysis");
  const sheets = clips.flatMap((c) =>
    (fs.existsSync(analysisDir) ? fs.readdirSync(analysisDir) : [])
      .filter((f) => f.startsWith(`${c.key}_sheet`) && f.endsWith(".jpg"))
      .sort((a, b) => Number(a.match(/sheet(\d+)/)?.[1]) - Number(b.match(/sheet(\d+)/)?.[1]))
      .map((f, i) => ({ key: c.key, from: i * 24, file: path.join(analysisDir, f) })),
  );
  const images = sheets.map((s) => ({ base64: fs.readFileSync(s.file).toString("base64"), mediaType: "image/jpeg" as const }));
  const brief = `${text}\n\nЛисты кадров приложены картинками, по порядку: ${sheets.map((s, i) => `${i + 1} — ${s.key} с ${s.from} с`).join(", ")}. Кадры через 0,5 с, метка в углу — время от начала листа.`;
  const system = planSystem();
  let draft = await claudeJson<Draft>(system, brief, { task: "news-plan", images });
  // последняя раскладка, прошедшая проверку: если правка смысла сломает её, ролик соберётся по ней (29.10 Язь падал,
  // когда последняя переделка по замечаниям смысла вышла с зацепкой длиннее 16 слов)
  let sound: Draft | null = null;
  let clean = false;
  let meaning = 0;
  for (let attempt = 0; attempt < 5; attempt++) {
    // заготовку остановили (пришло задание, prep.ts): дальше ролик идёт по раскладке, прошедшей правила
    if (hooks.signal?.aborted && sound) break;
    const errors = check(draft);
    // раскладка сошлась — проверка смысла: понятна ли каждая реплика без оригинала и верно ли пересказано
    if (!errors.length) {
      sound = draft;
      // замечания смысла исправлены rounds раз — дальше ролик идёт по раскладке, прошедшей правила
      if (meaning >= rounds) break;
      await hooks.step("Проверяем смысл", 44);
      errors.push(...(await contextProblems(story, draft, clips)));
      if (!errors.length) {
        clean = true;
        break;
      }
      meaning++;
    }
    if (attempt === 4) break;
    hooks.log(`черновик с ошибками: ${errors.join("; ")}`);
    // правка — на средней настройке: замечания точечные, весь сценарий заново Claude не придумывает
    draft = await claudeJson<Draft>(system, `${brief}\n\nТвой прошлый ответ:\n${JSON.stringify(draft)}\n\nИсправь ошибки и пришли весь JSON заново:\n${errors.map((e) => `- ${e}`).join("\n")}`, { task: "news-plan", images, effort: "medium" });
  }
  if (!clean && !check(draft).length) sound = draft;
  if (!clean && sound) hooks.log("замечания смысла исправлены не все — берём последнюю раскладку, прошедшую проверку");
  // концовка — отдельным шагом: после всех попыток проверка смысла всё ещё недовольна концом — переписываются только два
  // последних куска (владелец 30.10: «Женя, браво!» вместо прощального «Укуси меня, пчела»)
  if (!clean && sound && opts.ending && !hooks.signal?.aborted) {
    const base: Draft = sound;
    const ending = (await contextProblems(story, base, clips)).filter((p) => endingProblem(p, base.segments.length));
    if (ending.length) {
      await hooks.step("Переписываем концовку", 45);
      try {
        const fixed = await claudeJson<Draft>(system, `${brief}\n\nРаскладка:\n${JSON.stringify(base)}\n\nВсё в ней хорошо, кроме конца. Перепиши только два последних куска — реплику автора и кусок героя — по замечаниям; остальное оставь слово в слово и пришли весь JSON:\n${ending.map((e) => `- ${e}`).join("\n")}`, { task: "news-plan-ending", images });
        const still = check(fixed).length ? ending : (await contextProblems(story, fixed, clips)).filter((p) => endingProblem(p, fixed.segments.length));
        if (still.length < ending.length) {
          sound = fixed;
          hooks.log("концовка переписана отдельно");
        } else hooks.log(`концовка не стала лучше: ${still.join("; ")}`);
      } catch (error) {
        hooks.log(`концовка не переписалась: ${(error as Error).message}`);
      }
    }
  }
  const left = check(sound ?? draft);
  if (left.length) throw new Error(`Раскладка ролика не сошлась: ${left.slice(0, 3).join("; ")}`);
  draft = sound ?? draft;
  writeJson(cached, draft);
  return draft;
}
